-- TaviBloom product catalog. Prices are integer cents to avoid floating-point currency errors.
CREATE TABLE IF NOT EXISTS products (
  id INTEGER PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  price_cents INTEGER NOT NULL CHECK (price_cents >= 0),
  image_url TEXT NOT NULL,
  label TEXT NOT NULL DEFAULT 'Discover',
  type TEXT NOT NULL DEFAULT 'Discover',
  emoji TEXT NOT NULL DEFAULT '🧸',
  background_color TEXT NOT NULL DEFAULT '#f6e9de',
  description TEXT NOT NULL,
  details_json TEXT NOT NULL DEFAULT '[]',
  age_label TEXT NOT NULL DEFAULT '',
  is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_products_active_category ON products(is_active, category);
